using System;

namespace SimpleBase;

/// <summary>
/// Internal Base64 helpers.
/// </summary>
static class Base64
{
    const char paddingChar = '=';

    internal static byte[] DecodeUrl(ReadOnlySpan<char> text)
    {
        string base64 = convertBase64UrlToBase64(text);
        return Convert.FromBase64String(base64);
